//! Independent post-verification phase contracts using the real PostgreSQL store.
//! Fixed PHC strings are already-hashed fixture inputs, not password-test substitutes.
mod discord;
mod sessions;

use super::store;
use sqlx::{Connection, PgConnection, PgPool, postgres::PgPoolOptions};
use std::{
    sync::atomic::{AtomicU64, Ordering},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use url::Url;

// Fixed fixtures generated by libargon2's Argon2id v19 implementation with
// m=19456,t=2,p=1,hashlen=32 and separate fixed salts. No real credential is used.
const PHC: &str = "$argon2id$v=19$m=19456,t=2,p=1$cGhhc2UtZml4dHVyZS0wMQ$LCKMOmumi3UNCMDTo72M51kbs43LD8GHoQ4BVrOyxaY";
const OTHER_PHC: &str = "$argon2id$v=19$m=19456,t=2,p=1$cGhhc2UtZml4dHVyZS0wMg$0yD0VHI4N5CXJMOZ0qZvBGT+E/F8TDyMgbIrvjeAVwg";
const OWNER: &str = "phase_owner";
static COUNTER: AtomicU64 = AtomicU64::new(0);

fn identifier_is_owned(name: &str) {
    assert!(name.starts_with("keida_reborn_test_") && name.len() <= 63);
    assert!(
        name.bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
    );
}

fn verifier(index: u32) -> Vec<u8> {
    let mut bytes = vec![0xcc; 32];
    bytes[..4].copy_from_slice(&index.to_be_bytes());
    bytes
}

struct Fixture {
    admin_url: String,
    name: String,
    pool: PgPool,
    key: Vec<u8>,
    setup: Vec<u8>,
}

impl Fixture {
    async fn prepared() -> Self {
        let admin_url = std::env::var("REBORN_TEST_DATABASE_URL").expect(
            "REBORN_TEST_DATABASE_URL must provision a local disposable PostgreSQL fixture; store phase contracts never skip",
        );
        let mut parsed = Url::parse(&admin_url).expect("parse disposable administrator URL");
        assert!(matches!(parsed.scheme(), "postgres" | "postgresql"));
        assert!(matches!(
            parsed.host_str(),
            Some("127.0.0.1" | "localhost" | "[::1]" | "::1")
        ));
        let name = format!(
            "keida_reborn_test_{}_{:x}_{:x}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .expect("fixture clock")
                .as_nanos(),
            COUNTER.fetch_add(1, Ordering::Relaxed),
        );
        identifier_is_owned(&name);
        let mut admin = PgConnection::connect(&admin_url)
            .await
            .expect("connect disposable administrator");
        // Audited SQL: only the generated, checked identifier enters this string.
        sqlx::raw_sql(sqlx::AssertSqlSafe(format!("CREATE DATABASE \"{name}\"")))
            .execute(&mut admin)
            .await
            .expect("create owned phase database");
        parsed.set_path(&format!("/{name}"));
        let pool = PgPoolOptions::new()
            .max_connections(8)
            .acquire_timeout(Duration::from_secs(2))
            .connect(parsed.as_str())
            .await
            .expect("connect owned phase pool");
        crate::database::migrate(&pool)
            .await
            .expect("apply actual migrations");
        let fixture = Self {
            admin_url,
            name,
            pool,
            key: vec![11; 32],
            setup: vec![12; 32],
        };
        store::prepare_owner(&fixture.pool, &fixture.key, &fixture.setup)
            .await
            .expect("prepare actual store authority");
        fixture
    }

    async fn owned() -> (Self, store::Account, Vec<u8>) {
        let fixture = Self::prepared().await;
        let initial = verifier(1);
        let owner = store::claim(
            &fixture.pool,
            &fixture.key,
            &fixture.setup,
            OWNER,
            PHC,
            &initial,
        )
        .await
        .expect("claim fixture owner through actual store");
        (fixture, owner, initial)
    }

    async fn snapshot(&self) -> store::LoginSnapshot {
        store::reserve_login(&self.pool, &self.key, OWNER, 1)
            .await
            .expect("capture actual login snapshot")
            .expect("owner snapshot")
    }

    async fn counts(&self) -> (i64, i64) {
        let users = sqlx::query_scalar("SELECT COUNT(*) FROM users")
            .fetch_one(&self.pool)
            .await
            .expect("count fixture users");
        let sessions = sqlx::query_scalar("SELECT COUNT(*) FROM sessions")
            .fetch_one(&self.pool)
            .await
            .expect("count fixture sessions");
        (users, sessions)
    }

    async fn seed_sessions(&self, account: i64, additional: u32) -> Vec<Vec<u8>> {
        let mut seeded = Vec::new();
        for index in 2..(additional + 2) {
            let value = verifier(index);
            sqlx::query("INSERT INTO sessions (verifier,account_id,generation,created_at,expires_at) SELECT $1,id,generation,floor(extract(epoch FROM clock_timestamp()))::BIGINT,floor(extract(epoch FROM clock_timestamp()))::BIGINT + 43200 FROM users WHERE id = $2")
                .bind(&value).bind(account).execute(&self.pool).await.expect("seed owned valid session fixture");
            seeded.push(value);
        }
        seeded
    }

    async fn active_count(&self, account: i64) -> i64 {
        sqlx::query_scalar("SELECT COUNT(*) FROM sessions s JOIN users u ON u.id = s.account_id WHERE u.id = $1 AND s.revoked = FALSE AND s.generation = u.generation AND s.expires_at > floor(extract(epoch FROM clock_timestamp()))::BIGINT")
            .bind(account).fetch_one(&self.pool).await.expect("count current session authority")
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let admin_url = self.admin_url.clone();
        let name = self.name.clone();
        identifier_is_owned(&name);
        let result = std::thread::spawn(move || {
            let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().map_err(|_| ())?;
            runtime.block_on(async move {
                let mut admin = PgConnection::connect(&admin_url).await.map_err(|_| ())?;
                sqlx::query("SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = $1 AND pid <> pg_backend_pid()")
                    .bind(&name).execute(&mut admin).await.map_err(|_| ())?;
                // Same generated-identifier audit; never remove the supplied administrator DB.
                sqlx::raw_sql(sqlx::AssertSqlSafe(format!("DROP DATABASE \"{name}\"")))
                    .execute(&mut admin).await.map_err(|_| ())?;
                Ok::<(), ()>(())
            })
        }).join();
        if !matches!(result, Ok(Ok(()))) {
            eprintln!("owned store phase database cleanup failed");
        }
    }
}

#[tokio::test]
async fn captured_bootstrap_does_not_authorize_expired_changed_or_consumed_claim() {
    let fixture = Fixture::prepared().await;
    let captured = store::bootstrap(&fixture.pool, &fixture.key)
        .await
        .expect("capture admitted bootstrap");
    assert!(captured.expires > captured.now);
    sqlx::query("UPDATE auth_state SET setup_expires_at = 0 WHERE singleton = TRUE")
        .execute(&fixture.pool)
        .await
        .expect("expire only owned setup fixture");
    let result = store::claim(
        &fixture.pool,
        &fixture.key,
        &captured.hash,
        OWNER,
        PHC,
        &verifier(1),
    )
    .await;
    assert_eq!(result.err(), Some(store::Error::Rejected));
    assert_eq!(fixture.counts().await, (0, 0));
    let replacement = vec![13; 32];
    store::prepare_owner(&fixture.pool, &fixture.key, &replacement)
        .await
        .expect("prepare deliberate replacement after expiry");
    let result = store::claim(
        &fixture.pool,
        &fixture.key,
        &captured.hash,
        OWNER,
        PHC,
        &verifier(2),
    )
    .await;
    assert_eq!(result.err(), Some(store::Error::Rejected));
    assert_eq!(fixture.counts().await, (0, 0));
    let winner = store::claim(
        &fixture.pool,
        &fixture.key,
        &replacement,
        OWNER,
        PHC,
        &verifier(3),
    )
    .await
    .expect("claim current setup");
    for token in [&captured.hash, &replacement] {
        let result = store::claim(
            &fixture.pool,
            &fixture.key,
            token,
            "second_owner",
            PHC,
            &verifier(4),
        )
        .await;
        assert_eq!(result.err(), Some(store::Error::Conflict));
    }
    assert_eq!(fixture.counts().await, (1, 1));
    let owner_id: Option<i64> =
        sqlx::query_scalar("SELECT owner_id FROM auth_state WHERE singleton = TRUE")
            .fetch_one(&fixture.pool)
            .await
            .expect("inspect final owner identity");
    assert_eq!(owner_id, Some(winner.id));
}

#[tokio::test]
async fn captured_login_cannot_survive_generation_password_or_active_state_changes() {
    let (fixture, owner, initial) = Fixture::owned().await;
    let snapshot = fixture.snapshot().await;
    sqlx::query("UPDATE users SET generation = generation + 1 WHERE id = $1")
        .bind(owner.id)
        .execute(&fixture.pool)
        .await
        .expect("advance owned generation fixture");
    let result = store::finish_login(
        &fixture.pool,
        &fixture.key,
        &snapshot,
        &verifier(100),
        Some(&initial),
    )
    .await;
    assert_eq!(result.err(), Some(store::Error::Unauthorized));
    assert_eq!(fixture.counts().await, (1, 1));
    sqlx::query("UPDATE users SET generation = $2 WHERE id = $1")
        .bind(owner.id)
        .bind(snapshot.generation)
        .execute(&fixture.pool)
        .await
        .expect("restore only owned generation fixture");
    assert!(
        store::session(&fixture.pool, &fixture.key, &initial)
            .await
            .is_ok()
    );

    sqlx::query("UPDATE users SET password_phc = $2 WHERE id = $1")
        .bind(owner.id)
        .bind(OTHER_PHC)
        .execute(&fixture.pool)
        .await
        .expect("change owned verifier fixture");
    let result = store::finish_login(
        &fixture.pool,
        &fixture.key,
        &snapshot,
        &verifier(101),
        Some(&initial),
    )
    .await;
    assert_eq!(result.err(), Some(store::Error::Unauthorized));
    assert_eq!(fixture.counts().await, (1, 1));
    assert!(
        store::session(&fixture.pool, &fixture.key, &initial)
            .await
            .is_ok()
    );
    sqlx::query("UPDATE users SET password_phc = $2 WHERE id = $1")
        .bind(owner.id)
        .bind(PHC)
        .execute(&fixture.pool)
        .await
        .expect("restore only owned verifier fixture");

    sqlx::query("UPDATE users SET active = FALSE WHERE id = $1")
        .bind(owner.id)
        .execute(&fixture.pool)
        .await
        .expect("disable owned account fixture");
    let result = store::finish_login(
        &fixture.pool,
        &fixture.key,
        &snapshot,
        &verifier(102),
        Some(&initial),
    )
    .await;
    assert_eq!(result.err(), Some(store::Error::Unauthorized));
    assert_eq!(fixture.counts().await, (1, 1));
    sqlx::query("UPDATE users SET active = TRUE WHERE id = $1")
        .bind(owner.id)
        .execute(&fixture.pool)
        .await
        .expect("restore only owned active fixture");
    assert!(
        store::session(&fixture.pool, &fixture.key, &initial)
            .await
            .is_ok()
    );
    let current = store::finish_login(&fixture.pool, &fixture.key, &snapshot, &verifier(103), None)
        .await
        .expect("unchanged current snapshot can finalize");
    assert_eq!(current.id, owner.id);
}

#[tokio::test]
async fn cap_rotation_and_verifier_collision_preserve_atomic_old_session_authority() {
    let (fixture, owner, initial) = Fixture::owned().await;
    let other_devices = fixture.seed_sessions(owner.id, 31).await;
    assert_eq!(fixture.active_count(owner.id).await, 32);
    let snapshot = fixture.snapshot().await;
    let result =
        store::finish_login(&fixture.pool, &fixture.key, &snapshot, &verifier(100), None).await;
    assert_eq!(result.err(), Some(store::Error::Limited));
    assert_eq!(fixture.active_count(owner.id).await, 32);
    assert!(
        store::session(&fixture.pool, &fixture.key, &initial)
            .await
            .is_ok()
    );

    let rotated = verifier(101);
    store::finish_login(
        &fixture.pool,
        &fixture.key,
        &snapshot,
        &rotated,
        Some(&initial),
    )
    .await
    .expect("rotation replaces only presented session at cap");
    assert_eq!(fixture.active_count(owner.id).await, 32);
    assert_eq!(
        store::session(&fixture.pool, &fixture.key, &initial)
            .await
            .err(),
        Some(store::Error::Unauthorized)
    );
    assert!(
        store::session(&fixture.pool, &fixture.key, &other_devices[0])
            .await
            .is_ok()
    );

    let before = fixture.counts().await;
    let result = store::finish_login(
        &fixture.pool,
        &fixture.key,
        &snapshot,
        &other_devices[0],
        Some(&rotated),
    )
    .await;
    assert_eq!(result.err(), Some(store::Error::Conflict));
    assert_eq!(fixture.counts().await, before);
    assert_eq!(fixture.active_count(owner.id).await, 32);
    assert!(
        store::session(&fixture.pool, &fixture.key, &rotated)
            .await
            .is_ok(),
        "failed collision retired the previous session"
    );
    assert!(
        store::session(&fixture.pool, &fixture.key, &other_devices[0])
            .await
            .is_ok()
    );
}

#[tokio::test]
async fn concurrent_final_admission_from_thirty_one_never_creates_a_thirty_third_session() {
    let (fixture, owner, _) = Fixture::owned().await;
    fixture.seed_sessions(owner.id, 30).await;
    assert_eq!(fixture.active_count(owner.id).await, 31);
    let snapshot = fixture.snapshot().await;
    let first = verifier(200);
    let second = verifier(201);
    let (first_result, second_result) = tokio::time::timeout(Duration::from_secs(4), async {
        tokio::join!(
            store::finish_login(&fixture.pool, &fixture.key, &snapshot, &first, None),
            store::finish_login(&fixture.pool, &fixture.key, &snapshot, &second, None),
        )
    })
    .await
    .expect("bounded concurrent final admission");
    assert_eq!(
        usize::from(first_result.is_ok()) + usize::from(second_result.is_ok()),
        1
    );
    let rejected = if first_result.is_err() {
        first_result.err()
    } else {
        second_result.err()
    };
    assert_eq!(rejected, Some(store::Error::Limited));
    assert_eq!(fixture.active_count(owner.id).await, 32);
    let count: i64 =
        sqlx::query_scalar("SELECT COUNT(*) FROM sessions WHERE verifier = $1 OR verifier = $2")
            .bind(first)
            .bind(second)
            .fetch_one(&fixture.pool)
            .await
            .expect("inspect only submitted session verifiers");
    assert_eq!(count, 1);
}
